mapper.select:
SELECT COUNT(*) FROM business_outbox
WHERE state = 'DONE' AND consumed_at < #{cutoff}
  AND NOT EXISTS (
    SELECT 1 FROM message_failure f WHERE f.event_id = business_outbox.id
  )

mapper.delete:
DELETE FROM business_outbox
WHERE state = 'DONE' AND consumed_at < #{cutoff}
  AND NOT EXISTS (
    SELECT 1 FROM message_failure f WHERE f.event_id = business_outbox.id
  )
ORDER BY id
LIMIT #{limit}
